<section class="{{ $dayClasses }}">@foreach(range(0, 6) as $offset)@php($date = $weeklyFootball['weekStart']->copy()->addDays($offset))@php($dayMatches = $matchesByDay->get($date->format('Y-m-d'), collect()))<section class="day"><h2>{{ ucfirst($date->locale('nb')->translatedFormat('l j. F')) }}</h2>@forelse($dayMatches as $match)<article class="match"><time class="time">{{ $match['startsAt']->format('H.i') }}</time><div class="teams"><strong>@if($match['homeLogoUrl'])<img class="crest" src="{{ $match['homeLogoUrl'] }}" alt="" onerror="this.remove()">@endif{{ preg_replace('/\s+–\s+.*/u', '', $match['name']) }} – @if($match['awayLogoUrl'])<img class="crest" src="{{ $match['awayLogoUrl'] }}" alt="" onerror="this.remove()">@endif{{ preg_replace('/^.*\s+–\s+/u', '', $match['name']) }}</strong><span>{{ $match['competition'] }}</span></div><div class="channel">{{ implode(' · ', $match['channels']) }}</div></article>@empty @if(collect($weeklyFootball['unpublishedDates'])->contains(fn ($unpublishedDate) => $unpublishedDate->isSameDay($date)))<p class="empty">TV-programmet er foreløpig ikke publisert.</p>@elseif(collect($weeklyFootball['missingLocalDataDates'])->contains(fn ($missingDate) => $missingDate->isSameDay($date)))<p class="empty">Lokale TV-data mangler.</p>@else<p class="empty">Ingen oppført kamp.</p>@endif @endforelse</section>@endforeach</section>
